package com.dy.artisan3d.data.repositoryimport com.dy.artisan3d.data.model.ProductResponseimport com.dy.artisan3d.domain.model.ProductDetailsimport com.dy.artisan3d.domain.repository.ProductDetailRepositoryimport com.dy.artisan3d.util.Constants.BASE_URLimport io.ktor.client.HttpClientimport io.ktor.client.call.bodyimport io.ktor.client.request.getimport io.ktor.client.request.parameterimport kotlinx.coroutines.Dispatchersimport kotlinx.coroutines.IOimport kotlinx.coroutines.withContextimport com.dy.artisan3d.data.mapper.toDomainclass ProductDetailRepositoryImpl(    private val httpClient: HttpClient,) : ProductDetailRepository {    override suspend fun getProductDetail(        productId: Int,        language: String    ): Result<ProductDetails> = withContext(Dispatchers.IO) {        try {            val response = httpClient.get(BASE_URL+"products/$productId") {                parameter("lang", language)            }.body<ProductResponse>()            val product = response.data.toDomain(language)            Result.success(product)        } catch (e: Exception) {            Result.failure(e)        }    }}